"""Mutalia-e-Quran XII PDF30: p.27 — verses 4:77–80 (4:81 begins at the foot; recorded on p.28). Run: python class12_quran_page030.py"""
from class12_quran_common import BOOK, Builder, rec, V


def p30():
    b = Builder()
    V(b, 4, 77, 'کیا آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) نے ان لوگوں (کے حال) کو نہیں دیکھا جن سے کہا گیا تھا کہ اپنے ہاتھ روکے رکھو (قتال میں جلد بازی نہ کرو) اور نماز قائم کرو اور زکوٰۃ دو پھر جب اُن پر قتال کرنا لکھ دیا گیا اُس وقت اُن میں سے ایک گروہ لوگوں سے ڈرنے لگا جیسے اللہ سے ڈرا جاتا ہے یا اس سے بھی بڑھ کر ڈرنے (لگا) اور انھوں نے کہا اے ہمارے رب! تو نے ہم پر قتال کرنا کیوں فرض کر دیا ہمیں ایک قریبی مدت تک مہلت کیوں نہ دی آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) فرما دیجیے دنیا کا سامان تو بہت ہی تھوڑا ہے اور آخرت اُس کے لیے بہت بہتر ہے جس نے پرہیزگاری اختیار کی اور تم پر ذرہ برابر بھی ظلم نہیں کیا جائے گا۔',
      'ایا تاسو (صلی الله علیه وعلی آله واصحابه وسلم) د هغو خلکو (حال) نه دی لیدلی چې ورته ویل شوي وو: خپل لاسونه وساتئ (په جګړه کې بېړه مه کوئ)، لمونځ قایم کړئ او زکات ورکړئ؟ بیا کله چې پرې جګړه فرض کړای شوه، نو په هغه وخت کې له هغوی یوه ډله له خلکو داسې ووېرېده لکه له الله چې وېره کېږي یا له هغه هم زیاته (وېره پیل کړه)، او ویې ویل: «ای زموږ ربه! پر موږ دې جګړه ولې فرض کړه؟ موږ ته دې تر یوې نږدې مودې مهلت ولې رانه کړ؟» تاسو (صلی الله علیه وعلی آله واصحابه وسلم) ووایئ: د دنیا سامان ډېر لږ دی، او آخرت د هغه چا لپاره ډېر غوره دی چې پرهېزګاري یې غوره کړې، او پر تاسو به د ذرې په اندازه هم ظلم ونه شي.')
    V(b, 4, 78, 'تم جہاں کہیں بھی ہو موت تمھیں آ پکڑے گی اگرچہ تم مضبوط قلعوں میں ہو اور اگر انھیں کوئی سکھ پہنچے تو وہ کہتے ہیں یہ اللہ کے پاس سے ہے اور اگر انھیں کوئی دکھ پہنچے تو وہ کہتے ہیں یہ آپ کی وجہ سے ہے آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) فرما دیجیے یہ سب اللہ کے پاس سے ہے تو پھر اس قوم کو کیا ہوا ہے کہ کوئی بات سمجھنے کے قریب بھی نہیں آتے۔',
      'تاسو چې هر چېرې یاست، مرګ به مو ونیسي که څه هم په ټینګو کلاګانو کې یاست؛ او که هغوی ته کومه ښېګڼه ورسېږي، وایي: «دا د الله له لوري ده»، او که کوم تکلیف ورسېږي، وایي: «دا ستاسو له امله دی». تاسو (صلی الله علیه وعلی آله واصحابه وسلم) ووایئ: «دا ټول د الله له لوري دي». نو دې قوم ته څه شوي چې د کومې خبرې پوهېدو ته نږدې هم نه ورځي؟')
    V(b, 4, 79, '(اے مخاطب!) جو سکھ تجھے پہنچے تو وہ اللہ کی طرف سے ہے اور جو دکھ تجھے پہنچے تو وہ تیری طرف سے ہے اور ہم نے آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کو لوگوں کے لیے رسول بنا کر بھیجا ہے اور اللہ (آپ صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم کی رسالت پر بطور) گواہ کافی ہے۔',
      '(ای مخاطبه!) کومه ښېګڼه چې تا ته ورسېږي، هغه د الله له لوري ده، او کوم تکلیف چې تا ته ورسېږي، هغه ستا له لوري دی؛ او موږ تاسو (صلی الله علیه وعلی آله واصحابه وسلم) خلکو ته رسول لېږلی یاست، او الله (ستاسو پر رسالت د) شاهد (په توګه) بس دی.')
    V(b, 4, 80, 'جس نے رسول (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کی اطاعت کی تو یقیناً اُسی نے اللہ کی اطاعت کی اور جس نے (اطاعت سے) منہ پھیرا تو ہم نے آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کو اُن پر نگہبان بنا کر نہیں بھیجا۔',
      'چا چې د رسول (صلی الله علیه وعلی آله واصحابه وسلم) اطاعت وکړ، یقیناً هغه د الله اطاعت وکړ؛ او چا چې (له اطاعته) مخ واړاوه، نو موږ تاسو (صلی الله علیه وعلی آله واصحابه وسلم) پر هغوی ساتونکی نه یاست لېږلي.')
    BOOK.save(30, [(3, rec(b, 3, 30, 30))], issues=[{'id': 'mq12-pdf030', 'unit': 3, 'printedPage': 27,
               'description': 'Verse 4:81 begins at the foot of p.27 and is recorded with p.28.'}])


